"""Generate R2-S04 expectations and the pinned Python word-boundary data."""

from datetime import date, datetime
from pathlib import Path
import sys
import unicodedata


def word_boundaries() -> None:
    assert unicodedata.unidata_version == "15.0.0"
    edges = []
    previous = False
    for codepoint in range(128, 0x110000):
        current = chr(codepoint).isalnum()
        if current != previous:
            edges.append(codepoint)
        previous = current
    assert not previous
    print("// Generated by tests/fixtures/generate_core_gate.py (Python 3.12, Unicode 15.0).")
    print("\n// Non-ASCII half-open ranges for Python's regex word characters.")
    print("#[rustfmt::skip]\nconst WORD_BOUNDARIES: &[u32] = &[")
    for offset in range(0, len(edges), 10):
        print("    " + ", ".join(f"0x{n:x}" for n in edges[offset:offset + 10]) + ",")
    print("];")
    print("""
pub(crate) fn is_word(character: char) -> bool {
    if character.is_ascii() {
        return character.is_ascii_alphanumeric() || character == '_';
    }
    WORD_BOUNDARIES.partition_point(|&edge| edge <= u32::from(character)) % 2 != 0
}""")


def fixture(oracle_root: Path) -> None:
    sys.path.insert(0, str(oracle_root.resolve()))
    from nsl.core import encode_value
    from nsl.data_protection import (
        _CREDENTIAL_KEYS, CredentialMaterialError, ensure_no_credential_material,
    )

    def escaped(text: str) -> str:
        return (text.replace("\\", "\\\\").replace("\r", "\\r").replace("\n", "\\n")
                .replace("\t", "\\t").replace("\x1c", "\\x1c"))

    def credential(shape: str, marker: str, value: object) -> None:
        try:
            ensure_no_credential_material(value, "core gate fixture")
        except CredentialMaterialError:
            outcome = "reject"
        else:
            outcome = "accept"
        print(shape, escaped(marker), outcome, sep="\t")

    print("# Python Oracle 28a949ec96581cbdc52c8133527b23bb5b72ee0a")
    for label in sorted(_CREDENTIAL_KEYS):
        credential("key", label, {"meta": [{label: "demo-placeholder"}]})
        text = f"{label}=demo-placeholder"
        credential("text", text, {"note": ["normal", text]})

    for label in ("API-Key", "Client . Secret", "private_Key", "prİvate_key", "páassword", "public_key"):
        credential("key", label, {"meta": [{label: "demo-placeholder"}]})
    for shape, value in (("null", None), ("empty", ""), ("false", False), ("zero", 0), ("array", []), ("record", {})):
        credential(shape, "api_key", {"api_key": value})
    credential("null", "password=demo-placeholder", {"password=demo-placeholder": None})

    for text in (
        "", "ordinary demo-placeholder", "api_key", "api_key =   ", "api_key=;", "api_key=]",
        "api_key=", "api_key=\u00a0", "api_key=''", 'api_key=""', "api_key=[REDACTED]",
        "Authorization:\tBearer DEMO.STUB", "bearer\u00a0DEMO", "basic\nDEMO-._~+/=",
        "basİc K", "bearer #", "basic Æ", "Bearer", "unbearer DEMO", "aBearer DEMO",
        "éBearer DEMO", "🐍Bearer DEMO", "\u0345Bearer DEMO", "₂password=x", "猫password=x",
        "⸺password=x", "password😀=x", "password_=x", "api__key=x", "api---key=x",
        "APP_ACCESS_TOKEN=x", "access-token=x", "acceſs-tokeN=x", "prıvate_key=\u001cX",
        "eyJdemo.stub.signature", "AeyJdemo.stub.signature", "éeyJdemo.stub.signature",
        "eyJ.stub.signature", "eyJdemo..signature", "eyJdemo.stub.", "eyJdemo.stub.signature_",
        "-----BEGIN PRIVATE KEY-----\nDEMO\n-----END PRIVATE KEY-----",
        "------BEGIN RSA PRIVATE KEY-----\r\nDEMO\r\n------END OTHER 1 PRIVATE KEY-----",
        "-----BEGIN RSA PRIVATE KEY-----\nDEMO only",
        "-----begin PRIVATE KEY-----\nDEMO\n-----END PRIVATE KEY-----",
        "-----BEGIN  RSA PRIVATE KEY-----\nDEMO\n-----END PRIVATE KEY-----",
    ):
        credential("text", text, {"note": ["normal", text]})

    for value, parse in (
        ("0001-01-01", date.fromisoformat), ("2024-02-29", date.fromisoformat),
        ("9999-12-31", date.fromisoformat), ("2026-11-16T00:00:00Z", datetime.fromisoformat),
        ("2026-11-16T00:00:00.000001+00:00", datetime.fromisoformat),
        ("2026-11-16T09:30:00.009+09:30", datetime.fromisoformat),
        ("2026-11-16T00:00:00.123456-05:00", datetime.fromisoformat),
    ):
        encoded = encode_value(parse(value))
        print(encoded["$type"], encoded["value"], sep="\t")


if __name__ == "__main__":
    if sys.argv[1] == "--word-boundaries":
        word_boundaries()
    else:
        fixture(Path(sys.argv[1]))
